class Solution {
public:
    int countWords(vector<string>& words1, vector<string>& words2) {
        unordered_map<string, int> cnt1, cnt2;
        for (const string& w : words1) cnt1[w]++;
        for (const string& w : words2) cnt2[w]++;
        int ans = 0;
        for (const auto& [w, c] : cnt1) {
            if (c == 1) {
                auto it = cnt2.find(w);
                if (it != cnt2.end() && it->second == 1) ans++;
            }
        }
        return ans;
    }
};
